interface.definition:
a!localVariables(
  local!buDropDownUniqueValues: union(property(ri!buDropDown,"bu",null), property(ri!buDropDown,"bu",null)),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "Filters",
                    color: "STANDARD",
                    size: "MEDIUM",
                    style: "STRONG"
                  )
                }
              )
            }
          )       
        }
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
                choiceLabels: ri!fYearDropDown,
                choiceValues: ri!fYearDropDown,
                label: "Fiscal Year",
                placeholder: "Select Fiscal Year",
                value: ri!yearFilter,
                saveInto: {
                  ri!yearFilter,
                  a!save(
                    ri!documentId,
                    null
                  ),
                  a!save(
                    ri!paging,
                    #"SYSTEM_SYSRULES_pagingInfo"(
                      startIndex: 1,
                      batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                      sort: #"SYSTEM_SYSRULES_sortInfo"(field: "rotationalAskId")
                    )
                  )
                }
              )
            }
          ),
          /*a!columnLayout(*/
          /*contents: {*/
          /*a!multipleDropdownField(*/
          /*label: "Region",*/
          /*placeholder: "Select Region",*/
          /*choiceLabels: cons!CAW_TXT_ASK_REGION_LIST,*/
          /*choiceValues: {cons!CAW_INT_LABEL_EAST_ASK_REGION_ID,cons!CAW_INT_LABEL_WEST_ASK_REGION_ID},*/
          /*value: ri!regionFilter,*/
          /*saveInto: {*/
          /*ri!regionFilter,*/
          /*a!save(*/
          /*ri!documentId,*/
          /*null*/
          /*),*/
          /*a!save(*/
          /*ri!paging,*/
          /*a!pagingInfo(*/
          /*startIndex: 1,*/
          /*batchSize: cons!CAW_INT_GRID_BATCH_SIZE,*/
          /*sort: a!sortInfo(field: "rotationalAskId")*/
          /*)*/
          /*)*/
          /*}*/
          /*)*/
          /*}*/
          /*),*/
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_multipleDropdownField_v1"(
                choiceLabels: local!buDropDownUniqueValues,
                choiceValues: local!buDropDownUniqueValues,
                label: "BU",
                placeholder: "Select BU",
                value: ri!buFilter,
                saveInto: {
                  ri!buFilter,
                  a!save(
                    ri!documentId,
                    null
                  ),
                  a!save(
                    ri!paging,
                    #"SYSTEM_SYSRULES_pagingInfo"(
                      startIndex: 1,
                      batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
                      sort: #"SYSTEM_SYSRULES_sortInfo"(field: "rotationalAskId")
                    )
                  )
                },
                /*disabled: rule!CAW_isBlank(ri!regionFilter)*/
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            width: "2X"
          )
        }
      )
    },
    style: "ACCENT",
    marginBelow: "STANDARD"
  )
)
